INSERT INTO bot_documents (doc_name, data, updated_at) VALUES ('photo_orders_data.json', $arka${"orders": [{"id": 1, "user_id": 1481439247, "description": "یک دختر زشت", "price": 12000, "status": "waiting_payment", "receipt_text": null, "receipt_file_id": null, "delivered_photo_file_id": null, "created_at": "2026-08-17 09:32"}, {"id": 2, "user_id": 280742363, "description": "یک لگو رئال مادرید برام بساز", "price": 12000, "status": "waiting_payment", "receipt_text": null, "receipt_file_id": null, "delivered_photo_file_id": null, "created_at": "2026-08-22 17:20"}, {"id": 3, "user_id": 2059438307, "description": "سلام", "price": 12000, "status": "waiting_payment", "receipt_text": null, "receipt_file_id": null, "delivered_photo_file_id": null, "created_at": "2026-08-31 21:26"}, {"id": 4, "user_id": 1311982478, "description": "یه پروف دخترونه برای چنل\nاسم\n𝔭𝔦𝔫𝔨 𝔠𝔬𝔮𝔲𝔢𝔱𝔱𝔢 🎀💭\nایدی\n@softgirlvibe\nجذب کننده و دخترونه باشه", "price": 12000, "status": "waiting_payment", "receipt_text": null, "receipt_file_id": null, "delivered_photo_file_id": null, "created_at": "2026-09-04 19:27"}, {"id": 5, "user_id": 1973563598, "description": "سلامتی", "price": 12000, "status": "waiting_payment", "receipt_text": null, "receipt_file_id": null, "delivered_photo_file_id": null, "created_at": "2026-09-04 20:22"}, {"id": 6, "user_id": 1700079509, "description": "تصویری برام بساز که بیمه ملت همراه خانواده ها\nمشاور شما در بیمه ملت درخدمت شماست\nپاسخگویی به سوالات و نیازهای بیمه ای شما در سریعترین زمان", "price": 12000, "status": "waiting_payment", "receipt_text": null, "receipt_file_id": null, "delivered_photo_file_id": null, "created_at": "2026-09-05 04:16"}, {"id": 7, "user_id": 1012886348, "description": "عکس‌چیز بلند که ۱۵ سانت است و سرش نرم است و تهش مو دارد", "price": 12000, "status": "waiting_payment", "receipt_text": null, "receipt_file_id": null, "delivered_photo_file_id": null, "created_at": "2026-09-08 07:06"}, {"id": 8, "user_id": 2119417097, "description": "من به دادرس دارم داخل ب